/* One brand, separated by promotion state, with a truthful official-site exit. */
offerReady.then(({brands,promotions})=>{
const U=OFFER,b=brands.find(x=>x.id===new URLSearchParams(location.search).get('id'));if(!b){document.getElementById('main').innerHTML='<div class="container invalid-state"><h1>브랜드를 찾을 수 없습니다.</h1><p>링크를 확인하거나 다른 브랜드를 둘러보세요.</p><a class="button button-primary" href="favorites.html">브랜드 둘러보기 '+U.icon('arrow')+'</a></div>';return;}
const all=promotions.filter(p=>p.brandId===b.id),current=all.filter(U.active);let selected='all';document.title=b.name+' — OFFER';
document.getElementById('main').innerHTML='<div class="container page-content"><div class="brand-intro"><a class="text-link" href="favorites.html">← All Brands</a><div class="brand-title">'+U.brandLogo(b)+'<div><p class="eyebrow">'+U.escape(b.category.toUpperCase())+'</p><h1>'+U.escape(b.name)+'</h1></div></div><div class="brand-description"><strong>'+U.escape(b.koreanName)+'</strong><p>'+U.escape(b.description)+'</p></div></div><div class="brand-overview"><div class="brand-overview-actions">'+U.followButton(b)+'<a class="text-link" href="'+U.escape(b.url)+'" target="_blank" rel="noopener noreferrer">공식 홈페이지 '+U.icon('up')+'<span class="sr-only"> (새 탭)</span></a></div><p class="collection-count"><strong>'+current.length+'</strong>진행 중</p></div><div class="section-heading"><h2>From '+U.escape(b.name)+'<span>이 브랜드의 혜택을 한눈에 살펴보세요.</span></h2></div><div class="state-filters" id="brand-states" aria-label="브랜드 OFFER 진행 상태"></div><div class="brand-offers" id="brand-offers"></div></div>';
function render(){document.getElementById('brand-states').innerHTML=[['all','전체'],['active','진행 중'],['upcoming','예정'],['ended','종료']].map(([key,label])=>'<button class="filter" type="button" data-state="'+key+'" aria-pressed="'+(selected===key)+'">'+label+' <span>'+all.filter(p=>U.matchesState(p,key)).length+'</span></button>').join('');const visible=all.filter(p=>U.matchesState(p,selected));document.getElementById('brand-offers').innerHTML=visible.length?U.grid(visible):'<div class="empty-state"><div><h3>이 상태의 OFFER가 아직 없어요.</h3><p>전체 목록에서 이 브랜드의 다른 혜택을 확인할 수 있어요.</p></div><button class="button button-primary" type="button" data-show-all>전체 혜택 보기 '+U.icon('arrow')+'</button></div>';}
document.getElementById('brand-states').addEventListener('click',e=>{const b=e.target.closest('[data-state]');if(b){selected=b.dataset.state;render();document.querySelector('[data-state="'+selected+'"]').focus();}});document.getElementById('brand-offers').addEventListener('click',e=>{if(e.target.closest('[data-show-all]')){selected='all';render();document.querySelector('[data-state="all"]').focus();}});render();
});
